function depth(rule, d) {
  const out = ROOT + '/rules/' + rule.rule + '/' + d.file
  return agent(`Model rationale: opus — text that becomes an enforced rule; a wrong MUST propagates into every future diff.

${CONTEXT}

YOUR FILE: ${out}  (depth file of the ${rule.rule} rule; ID family ${d.family}; loads when the index routes here for: ${d.task_hint})
SOURCES (read in full): ${d.sources.map(s => RESEARCH + '/' + s).join(', ')}
${d.extra ? '\nADDITIONAL INSTRUCTIONS:\n' + d.extra + '\n' : ''}
Write the depth file: frontmatter (title, summary naming the family and what it owns), a one-paragraph scope stating what the family owns and which sibling families own the neighbours (by family name, never by file link), a Contents line, a "Dates and Floors" block naming the Nix, nixpkgs, tool versions and implementations the rows assume, then sections grouped by the check that catches them — each section opens with the gate command(s) stated once and a rule table (| ID | Rule | Rationale | Verification | Severity |) whose rows keep their consolidation IDs verbatim, followed by at most one minimal wrong/right Nix snippet pair per section where the mistake is easier shown than told, then "## What Agents Get Wrong Here" ranked from the consolidation's failure modes. Apply the authoring notes: drop the IDs they name, keep the pinned defaults they set, mark pinned rows, cite the version floors. Where two consolidations conflict, the "Cross-consolidation contradictions" resolution wins. Then run the checker on your file, fix, and return the receipt (hoist_to_index names the 1-3 rows the index must carry as non-negotiables).`,
    { label: 'depth:' + rule.rule + '/' + d.file, phase: 'Depth', model: 'opus', effort: 'high', schema: DEPTH_SCHEMA })
}

function index(rule, depthReceipts) {
  const out = ROOT + '/rules/' + rule.rule + '.md'
  const ok = depthReceipts.filter(Boolean)
  return agent(`Model rationale: opus — the index is the always-loaded surface; every line is paid for in every session.

${CONTEXT}

YOUR FILE: ${out}  (the index of the ${rule.rule} rule)
GLOBS (decided by the map and the authoring notes; copy exactly into frontmatter paths): ${JSON.stringify(rule.glob_list)}
DEPTH FILES already written by sibling drafters (read each in full): ${ok.map(r => r.path).join(', ')}
Their receipts (hoist candidates and routing phrases): ${JSON.stringify(ok.map(r => ({ path: r.path, hoist: r.hoist_to_index, routing: r.routing_row })))}
CONSOLIDATIONS for the index-owned ${rule.core_family} family and the gate: ${rule.index_sources.map(s => RESEARCH + '/' + s).join(', ')}
${rule.extra ? '\nADDITIONAL INSTRUCTIONS:\n' + rule.extra + '\n' : ''}
Write the index in the exact shape of ${ROOT}/rules/go-quality.md: frontmatter (paths = the globs above, summary, keywords, license Apache-2.0, repository https://github.com/ocx-sh/grimoire-lore), a two-line stance, Contents, "## The Gate" (the exact commands, narrowest first, pinned tool versions, chained into one named target), "## Non-Negotiables" (a numbered table of 12-18 merge-blocking rows, each citing depth IDs; hoist from the receipts, then prune to what must be true in every edit), "## Rules This File Owns" (the ${rule.core_family} rows the authoring notes assign to the index: at least the never-weaken-the-check rule, the watched-go-red rule, the empty-output rule, read-the-pinned-nixpkgs-and-implementation-first, generated-Nix handling), "## Where the Depth Is" (one task-worded row per depth file, routed by what the reader is doing, plus the sibling-set rows the notes name), "## Severity", "## Siblings". Under 200 lines. Every depth ID cited must exist in a depth file (grep them). Run the checker on the rule file with its support directory, fix, return the receipt.`,
    { label: 'index:' + rule.rule, phase: 'Index', model: 'opus', effort: 'high', schema: INDEX_SCHEMA })
}

function standalone(item) {
  return agent(`Model rationale: opus — ${item.kind === 'skill' ? 'a procedure agents run unattended; its steps and its refusal conditions are decisions' : 'an architecture decision record for a sibling repository; its decisions bind a future implementation'}.

${CONTEXT}

YOUR OUTPUT: ${item.path}
SOURCES (read in full): ${item.sources.map(s => s.startsWith('/') ? s : RESEARCH + '/' + s).join(', ')}

${item.brief}

Run the checker on your output, fix, return the receipt.`,
    { label: item.kind + ':' + item.path.split('/').slice(-2).join('/'), phase: 'Standalone', model: 'opus', effort: 'high', schema: STANDALONE_SCHEMA })
}

// ---------------------------------------------------------------- Run
const nDepth = PLAN.rules.reduce((n, r) => n + r.depth.length, 0)
log('Authoring: ' + PLAN.rules.length + ' rules, ' + nDepth + ' depth files, ' + PLAN.standalone.length + ' standalone')

const ruleResults = pipeline(
  PLAN.rules,
  rule => parallel(rule.depth.map(d => () => depth(rule, d))),
  (receipts, rule) => {
    const ok = receipts.filter(Boolean)
    if (ok.length < rule.depth.length) log(rule.rule + ': ' + (rule.depth.length - ok.length) + ' depth drafter(s) dropped; index proceeds with ' + ok.length)
    if (!ok.length) return { rule: rule.rule, depth: receipts, index: null }
    return index(rule, ok).then(ix => ({ rule: rule.rule, depth: receipts, index: ix }))
  },
)
const standaloneResults = parallel(PLAN.standalone.map(item => () => standalone(item)))
const [rules, standaloneOut] = await Promise.all([ruleResults, standaloneResults])

const dropped = rules.filter(Boolean).flatMap(r => (r.depth || []).filter(Boolean).flatMap(d => d.rule_ids_dropped || []))
const unclean = [
  ...rules.filter(Boolean).flatMap(r => (r.depth || []).filter(Boolean).filter(d => !d.checker_clean).map(d => d.path)),
  ...rules.filter(Boolean).filter(r => r.index && !r.index.checker_clean).map(r => r.index.path),
  ...standaloneOut.filter(Boolean).filter(s => !s.checker_clean).flatMap(s => s.paths),
]
log('Done: ' + rules.filter(r => r && r.index).length + '/' + PLAN.rules.length + ' indexes · ' + dropped.length + ' IDs dropped at authoring · ' + unclean.length + ' files still unclean')
return { rules, standalone: standaloneOut, dropped_ids: dropped, unclean }
